def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching with support for literal characters, 
    '.', '*', and '+' using a recursive backtracking algorithm.
    """

    def is_match(p: str, t: str) -> bool:
        if not p:
            return not t
        first_match = bool(t) and (p[0] == t[0] or p[0] == '.')

        if len(p) >= 2 and p[1] in '*+':
            if p[1] == '*':
                return (is_match(p[2:], t) or
                        (first_match and is_match(p, t[1:])))
            elif p[1] == '+':
                return first_match and (is_match(p[2:], t[1:]) or
                                        (first_match and is_match(p, t[1:])))
        else:
            return first_match and is_match(p[1:], t[1:])

    return is_match(pattern, text)

def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching with support for literal characters, 
    '.', '*', and '+' using dynamic programming to build a 2D table to 
    track matches between the pattern and the text.
    """

    m, n = len(text), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]
        elif pattern[j - 1] == '+':
            dp[0][j] = j > 1 and dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j - 1] == text[i - 1] or pattern[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] if (pattern[j - 2] == text[i - 1] or pattern[j - 2] == '.') else False)
            elif pattern[j - 1] == '+':
                dp[i][j] = dp[i - 1][j] if (pattern[j - 2] == text[i - 1] or pattern[j - 2] == '.') else False

    return dp[m][n]

