    """
    Implements regex matching with support for literal characters, 
    '.', '*', and '+' using dynamic programming with memoization.
    """

    memo = {}

    def dp(i: int, j: int) -> bool:
        if (i, j) in memo:
            return memo[(i, j)]
        if j == len(pattern):
            result = i == len(text)
        else:
            first_match = i < len(text) and (text[i] == pattern[j] or pattern[j] == '.')
            if j + 1 < len(pattern) and pattern[j + 1] in '*+':
                if pattern[j + 1] == '*':
                    result = (dp(i, j + 2) or 
                              (first_match and dp(i + 1, j)))
                else:  # pattern[j + 1] == '+'
                    result = first_match and (dp(i + 1, j) or dp(i, j + 2))
            else:
                result = first_match and dp(i + 1, j + 1)

        memo[(i, j)] = result
        return result

    return dp(0, 0)

